#define _POSIX_C_SOURCE 200809L
#include <assert.h>
#include <dlfcn.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/resource.h>
#include <time.h>

typedef void* (*heap_new_fn)(void);
typedef void* (*heap_malloc_fn)(void*,size_t);
typedef void (*heap_destroy_fn)(void*);
typedef void (*collect_fn)(bool);
static uint64_t now(void) { struct timespec t; assert(clock_gettime(CLOCK_MONOTONIC,&t)==0); return (uint64_t)t.tv_sec*1000000000u+(uint64_t)t.tv_nsec; }
static void cycle(heap_new_fn new_heap,heap_malloc_fn allocate,heap_destroy_fn destroy,collect_fn collect,size_t size,size_t live) {
  void* heap=new_heap();assert(heap);
  for(size_t i=0;i<live;i++) { volatile unsigned char* block=allocate(heap,size);assert(block);block[0]=(unsigned char)i;block[size-1]=(unsigned char)(i>>8); }
  destroy(heap);collect(true);
}
int main(int argc,char**argv) {
  assert(argc==4);size_t size=strtoull(argv[1],0,10),live=strtoull(argv[2],0,10),rounds=strtoull(argv[3],0,10);assert(size&&live&&rounds);
  heap_new_fn new_heap=(heap_new_fn)dlsym(RTLD_DEFAULT,"mi_heap_new");heap_malloc_fn allocate=(heap_malloc_fn)dlsym(RTLD_DEFAULT,"mi_heap_malloc");heap_destroy_fn destroy=(heap_destroy_fn)dlsym(RTLD_DEFAULT,"mi_heap_destroy");collect_fn collect=(collect_fn)dlsym(RTLD_DEFAULT,"mi_collect");assert(new_heap&&allocate&&destroy&&collect);
  for(size_t i=0;i<32;i++)cycle(new_heap,allocate,destroy,collect,size,live);
  struct rusage before,after;assert(getrusage(RUSAGE_SELF,&before)==0);uint64_t start=now();
  for(size_t i=0;i<rounds;i++)cycle(new_heap,allocate,destroy,collect,size,live);
  uint64_t elapsed=now()-start;assert(getrusage(RUSAGE_SELF,&after)==0);
  printf("{\"size\":%zu,\"live\":%zu,\"rounds\":%zu,\"allocations\":%zu,\"wall_ns\":%llu,\"minor_faults\":%ld,\"major_faults\":%ld,\"peak_rss_kib\":%ld}\n",size,live,rounds,live*rounds,(unsigned long long)elapsed,after.ru_minflt-before.ru_minflt,after.ru_majflt-before.ru_majflt,after.ru_maxrss);
}

