import hashlib
import json
import subprocess
import time
from pathlib import Path

p = Path(__file__).resolve().parent
stages = [p.parent / 'borrowed-operations-20261024', p]
checked = {}

def check(path, expected):
    path = Path(path)
    key = str(path)
    actual = hashlib.sha256(path.read_bytes()).hexdigest()
    assert actual == expected, (path, expected, actual)
    checked[key] = dict(sha256=actual, bytes=path.stat().st_size)

def visit(value):
    if isinstance(value, dict):
        if isinstance(value.get('sha256'), str):
            path = value.get('path', value.get('executable'))
            if isinstance(path, str):
                check(path, value['sha256'])
        if isinstance(value.get('library'), str) and isinstance(value.get('library_sha256'), str):
            check(value['library'], value['library_sha256'])
        for child in value.values():
            visit(child)
    elif isinstance(value, list):
        for child in value:
            visit(child)

for stage in stages:
    assert json.loads((stage / 'final-comparisons-status.json').read_text()).get('finished_utc')
    for label in ['baseline', 'final']:
        manifest = json.loads((stage / f'{label}-build-manifest.json').read_text())
        for config, build in manifest['builds'].items():
            check(stage / f'{label}-{config}.s', build['assembly_sha256'])
            if 'rlib_sha256' in build:
                check(Path(build['target_dir']) / 'release/libmechanical_mimalloc.rlib', build['rlib_sha256'])
            else:
                check(stage / f'{label}-{config}.so', build['library_sha256'])
    files = ['baseline-page-batch-build-manifest.json', 'final-page-batch-build-manifest.json', 'final-benchmark-manifest.json', 'facade-comparison.json', 'arena-final-comparison.json']
    files += [f.name for f in stage.glob('holdout-*.json') if not f.name.endswith('-plan.json')]
    for name in files:
        visit(json.loads((stage / name).read_text()))
    native = json.loads((stage / 'native-harness-manifest.json').read_text())
    for name, sha in native['sha256'].items():
        check(native[name], sha)

native_path = p / 'native-harness-manifest.json'
previous = json.loads(native_path.read_text())
cache_manifest = Path(previous['cache']) / 'artifacts.json'
native = json.loads(cache_manifest.read_text())
assert native['configuration'] == previous['configuration']
assert native['sha256'] == previous['sha256']
for name, sha in native['sha256'].items():
    check(native[name], sha)
worktree = Path((p / 'baseline-worktree.txt').read_text().strip())
native.update(artifact_manifest_sha256=hashlib.sha256(cache_manifest.read_bytes()).hexdigest(), baseline_worktree_commit=subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=worktree, text=True).strip(), baseline_worktree_dirty=bool(subprocess.check_output(['git', 'status', '--porcelain'], cwd=worktree, text=True)))
assert not native['baseline_worktree_dirty']
native_path.write_text(json.dumps(native, indent=2) + '\n')
result = dict(checked_utc=time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()), result='All recorded measured input fingerprints match the files after timing; cached native harness configuration and all binary hashes match the initial experiment.', files=checked)
(p / 'holdout-measured-input-check.json').write_text(json.dumps(result, indent=2) + '\n')
print('Verified', len(checked), 'measured input files')

