use mechanical_mimalloc::MiMalloc;
use std::alloc::{GlobalAlloc, Layout};
use std::time::Instant;

const LIVE: usize = 4096;

#[inline(never)]
fn batches(size: usize, count: usize) {
    let layout = Layout::from_size_align(size, 8).unwrap();
    let allocator = MiMalloc;
    let mut blocks = [std::ptr::null_mut(); LIVE];
    for _ in 0..count {
        for block in &mut blocks {
            // The layout is valid and each allocation is held until its matching free.
            *block = unsafe { allocator.alloc(layout) };
            assert!(!block.is_null());
            for offset in 0..size {
                // This allocation owns all `size` bytes until the free below.
                unsafe { block.add(offset).write_volatile(offset as u8) };
            }
        }
        for &block in &blocks[..LIVE / 2] {
            // Each live pointer is freed exactly once with the original layout.
            unsafe { allocator.dealloc(block, layout) };
        }
        for &block in blocks[LIVE / 2..].iter().rev() {
            // The second half is disjoint from the pointers already freed.
            unsafe { allocator.dealloc(block, layout) };
        }
    }
}

fn main() {
    let mut args = std::env::args().skip(1);
    let size: usize = args.next().unwrap().parse().unwrap();
    let count: usize = args.next().unwrap().parse().unwrap();
    assert!(args.next().is_none());
    batches(size, 2);
    let started = Instant::now();
    batches(size, count);
    println!("{}", started.elapsed().as_nanos());
}

