import json
import math
import statistics
from pathlib import Path

p = Path(__file__).resolve().parent
output = {"suites": {}, "review_cases": [], "review_aggregates": []}


def add(name, rows):
    groups = {}
    for row in rows:
        config = row.get("config", name)
        groups.setdefault(config, []).append(row)
        if row["median_ratio"] > 1.03:
            output["review_cases"].append({"suite": name, **row})
    summary = []
    for config, cases in groups.items():
        ratio = math.exp(statistics.mean(math.log(r["median_ratio"]) for r in cases))
        summary.append({"config": config, "cases": len(cases), "geomean_ratio": ratio})
        if ratio > 1.01:
            output["review_aggregates"].append({"suite": name, "config": config, "geomean_ratio": ratio})
    output["suites"][name] = {"groups": summary, "rows": rows}


for config in ["interpose", "interpose-secure"]:
    f = p / f"final-screen-{config}.json"
    if f.exists():
        data = json.loads(f.read_text())
        trace = [json.loads(line) for line in (p / f"final-screen-{config}-raw.jsonl").read_text().splitlines()]
        times = {}
        for run in trace:
            assert run["returncode"] == 0
            env = run["environment"]
            scenario = env["MIMALLOC_BENCH_SCENARIOS"]
            label = "baseline" if Path(env["MIMALLOC_RUST_LIB"]).name.startswith("baseline-") else "final"
            raw = [json.loads(line[6:])["ns"] for line in run["stdout"].splitlines() if line.startswith("QUICK {")]
            assert raw
            measured = raw if len(raw) == 1 else raw[1:]
            times.setdefault(scenario, {}).setdefault(label, []).append(statistics.median(measured))
        for row in data["rows"]:
            values = times[row["scenario"]]
            ratios = [c / b for b, c in zip(values["baseline"], values["final"])]
            assert len(ratios) == len(values["baseline"]) == len(values["final"]) == len(row["ratios"])
            assert ratios == row["ratios"]
            assert statistics.median(ratios) == row["median_ratio"]
        add(f"native-{config}", data["rows"])

for name, file in [("facade", "facade-comparison.json"), ("arena", "arena-final-comparison.json"), ("page_collection", "page-batch-comparison.json")]:
    f = p / file
    if f.exists():
        data = json.loads(f.read_text())
        if "results" in data:
            add(name, data["results"])

resource_rows = []
for config in ["interpose", "interpose-secure"]:
    files = {label: p / f"final-resources-{config}-{label}.jsonl" for label in ["baseline", "final"]}
    if not all(f.exists() for f in files.values()):
        continue
    records = {label: [json.loads(line) for line in f.read_text().splitlines()] for label, f in files.items()}
    for scenario in ["alloc_free", "remote_free_1x1"]:
        runs = {label: sorted([r for r in rows if r["scenario"] == scenario], key=lambda r: r["repeat"]) for label, rows in records.items()}
        assert [r["repeat"] for r in runs["baseline"]] == [r["repeat"] for r in runs["final"]]
        ratios = [c["wall_ns"] / b["wall_ns"] for b, c in zip(runs["baseline"], runs["final"])]
        resources = {}
        for label, values in runs.items():
            resources[label] = {key: statistics.median(r[key] for r in values) for key in values[0] if all(isinstance(r.get(key), (int, float)) and not isinstance(r[key], bool) for r in values)}
        resource_rows.append({"config": config, "scenario": scenario, "ratios": ratios, "median_ratio": statistics.median(ratios), "numeric_medians": resources})
