    add("resources", resource_rows)

(p / "comparison-summary.json").write_text(json.dumps(output, indent=2) + "\n")
for name, data in output["suites"].items():
    for group in data["groups"]:
        print(name, group["config"], group["cases"], "cases", f'{(group["geomean_ratio"] - 1) * 100:+.3f}%')
for kind in ["review_cases", "review_aggregates"]:
    print(kind, json.dumps(output[kind], indent=2))

